543	    /**
544	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
545	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
546	     * is deterministic in the email.
547	     *
548	     * @param email the owner's email, possibly {@code null}
549	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
550	     */
551	    public static String contactPreference(String email) {
552	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
553	    }
